#[path = "solution.rs"]
mod solution;

use solution::{IdentityBook, IdentityError, Permission};

#[test]
fn adds_entries_with_sequential_ids_and_observers() {
    let mut book = IdentityBook::new();
    assert!(book.is_empty());
    assert_eq!(book.len(), 0);
    assert_eq!(book.add("a@example.com".to_string(), "alpha".to_string(), Permission::Reader), Ok(1));
    assert_eq!(book.add("b@example.com".to_string(), "beta".to_string(), Permission::Owner), Ok(2));
    assert_eq!(book.len(), 2);
    assert!(!book.is_empty());
    assert_eq!(book.permission("a@example.com"), Some(Permission::Reader));
    assert_eq!(book.permission("b@example.com"), Some(Permission::Owner));
    assert_eq!(book.permission("missing@example.com"), None);
}

#[test]
fn authentication_requires_address_and_secret_to_match_same_entry() {
    let mut book = IdentityBook::new();
    book.add("a@example.com".to_string(), "alpha".to_string(), Permission::Reader).unwrap();
    book.add("b@example.com".to_string(), "beta".to_string(), Permission::Owner).unwrap();

    assert!(book.authenticate("a@example.com", "alpha"));
    assert!(book.authenticate("b@example.com", "beta"));
    assert!(!book.authenticate("a@example.com", "wrong"));
    assert!(!book.authenticate("missing@example.com", "alpha"));
    assert!(!book.authenticate("a@example.com", "beta"));
    assert!(!book.authenticate("", ""));
    assert!(!book.authenticate("", "alpha"));
}

#[test]
fn addresses_are_exact_and_case_sensitive() {
    let mut book = IdentityBook::new();
    book.add("User@Example.com".to_string(), "secret".to_string(), Permission::Owner).unwrap();
    assert!(book.authenticate("User@Example.com", "secret"));
    assert!(!book.authenticate("user@example.com", "secret"));
    assert_eq!(book.permission("user@example.com"), None);
}

#[test]
fn invalid_additions_are_atomic_and_do_not_consume_ids() {
    let mut book = IdentityBook::new();
    assert!(matches!(book.add(String::new(), "s".to_string(), Permission::Reader), Err(IdentityError::EmptyAddress)));
    assert!(matches!(book.add("a".to_string(), String::new(), Permission::Reader), Err(IdentityError::EmptySecret)));
    assert_eq!(book.len(), 0);

    assert_eq!(book.add("a".to_string(), "first".to_string(), Permission::Reader), Ok(1));
    assert!(matches!(book.add("a".to_string(), "second".to_string(), Permission::Owner), Err(IdentityError::DuplicateAddress)));
    assert_eq!(book.len(), 1);
    assert!(book.authenticate("a", "first"));
    assert!(!book.authenticate("a", "second"));
    assert_eq!(book.permission("a"), Some(Permission::Reader));
    assert_eq!(book.add("b".to_string(), "third".to_string(), Permission::Owner), Ok(2));
}

#[test]
fn observers_do_not_change_book_contents() {
    let mut book = IdentityBook::new();
    book.add("a".to_string(), "s".to_string(), Permission::Reader).unwrap();
    for _ in 0..3 {
        assert!(book.authenticate("a", "s"));
        assert_eq!(book.permission("a"), Some(Permission::Reader));
        assert_eq!(book.len(), 1);
        assert!(!book.is_empty());
    }
}

